#include <cstdint>
#include <iostream>
#include <vector>
#include <stdexcept>
int main(int argc,char**){bool profile=argc>1;int cases;std::cin>>cases;while(cases--){int n;std::cin>>n;if(n<1||n>20)throw std::runtime_error("order bound");std::vector<unsigned> out(n),in(n);for(auto&r:out)std::cin>>r;for(int i=0;i<n;++i)for(int j=0;j<n;++j)if(out[i]>>j&1)in[j]|=1u<<i;unsigned end=1u<<n;std::vector<uint64_t>d(size_t(end)*n),total(profile?end:0);std::vector<unsigned char>b(profile?size_t(end)*n:0),c(profile?size_t(end)*n:0),tb(profile?end:0),tc(profile?end:0);uint64_t answer=0;unsigned qb=0,qc=0;for(unsigned S=1;S<end;++S){unsigned rem=S;while(rem){unsigned z=rem&-rem;rem-=z;int v=__builtin_ctz(z);unsigned M=S^z;size_t ix=size_t(S)*n+v;if(!M){d[ix]=1;}else{unsigned choices=M&in[v];uint64_t H=0;unsigned B=profile?total[M]&7:0,C=profile?tb[M]:0;while(choices){unsigned x=choices&-choices;choices-=x;int u=__builtin_ctz(x);size_t iy=size_t(M)*n+u;H+=d[iy];if(profile){B+=b[iy];C+=c[iy];}}d[ix]=H;if(profile){b[ix]=B&7;c[ix]=C&7;}}if(profile){total[S]+=d[ix];tb[S]=(tb[S]+b[ix])&7;tc[S]=(tc[S]+c[ix])&7;}}}for(int v=0;v<n;++v){size_t ix=size_t(end-1)*n+v;answer+=d[ix];if(profile){qb+=b[ix];qc+=c[ix];}}std::cout<<answer;if(profile)std::cout<<' '<<(qb&7)<<' '<<(qc&7);std::cout<<'\n';}}
